        // different known reserved operation whose descriptor cannot match it.
        let wrapper = hostile
            .functions
            .iter_mut()
            .find(|function| !function.type_parameters.is_empty())
            .unwrap();
        wrapper.stable_id = if provider.contains("module std.collections") {
