    /// constructors above never choose this payer.
    #[cfg(test)]
    pub(super) fn with_skeleton_limit_oracle(limit: usize, lease: OracleLease) -> Self {
        Self {
            payer: AllocationPayer::Oracle(lease),
            ..Self::with_skeleton_limit(limit)
        }
    }

