    /// ceiling is applied; that ceiling and its refusal text are unchanged. A
    /// refused or sticky account is a refusal here, never a skipped debit.
    pub(super) fn charge_oracle_work(
        &mut self,
        function: &ResolvedFunction,
        units: usize,
        phase: &str,
    ) -> Result<(), Diagnostic> {
