                            std::iter::once(function),
                            &mut budget,
                        )
                        .unwrap();
                        let mut results = Vec::new();
                        for ty in function
                            .params
                            .iter()
                            .map(|p| &p.ty)
                            .chain(std::iter::once(&function.return_type))
                        {
                            results.push((
                                crate::cleanup::type_needs_resource_cleanup(&program, ty)
                                    .map_err(|m| Diagnostic::io("SPX-H006", m)),
                                inventory_needs_drop(
